# Completa la línea marcada y compruébala con py check.
def gini(etiquetas):
    cuenta = {}
    for e in etiquetas:
        cuenta[e] = cuenta.get(e, 0) + 1
    n = len(etiquetas)
    return 1 - 0   # ← cambia esta línea: resta la suma de (veces / n) al cuadrado

print(gini(["abuso", "abuso", "normal", "normal"]))   # 0.5
